    public ReportIncomeExpense(MainWin mainwin) {
        super(mainwin.getRoot(), mainwin.getRoot().MlM("Income / Expenses") + " - " + mainwin.getAZ().title);
        this.mainwin = mainwin;
        dateFrom = new DBDateTime("dateFrom");
        dateTill = new DBDateTime("dateTill");
        initComponents();

        FixNimbusBackgroundColor.fixNimbusBackgroundColor(jReport);

        // restore last used values for this billing period
        jTStartBalance.setText(root.getSetup().getLocalConfig(CONFIG_START_BALANCE + mainwin.getAZ().title, "0.0"));

        bindVar(jDateFrom, dateFrom);
        bindVar(jDateTill, dateTill);

        jDateFrom.setTextEditable(true);
        jDateTill.setTextEditable(true);

        var_to_gui();

        String savedFrom = root.getSetup().getLocalConfig(CONFIG_DATE_FROM + mainwin.getAZ().title, "");
        String savedTill = root.getSetup().getLocalConfig(CONFIG_DATE_TILL + mainwin.getAZ().title, "");
        if (!savedFrom.isEmpty() && savedFrom.length() == 10) {
            savedFrom = savedFrom + " 00:00:00";
        }
        jDateFrom.setDate(savedFrom);
        if (!savedTill.isEmpty() && savedTill.length() == 10) {
            savedTill = savedTill + " 00:00:00";
        }
        jDateTill.setDate(savedTill);
    }

    @Override
    public void close() {
        gui_to_var();
        root.getSetup().setLocalConfig(CONFIG_START_BALANCE + mainwin.getAZ().title, jTStartBalance.getText().trim());

        String fromDate = jDateFrom.getDate();
        root.getSetup().setLocalConfig(CONFIG_DATE_FROM + mainwin.getAZ().title,
                fromDate != null && fromDate.length() >= 10 ? fromDate.substring(0, 10) : fromDate);
        String tillDate = jDateTill.getDate();
        root.getSetup().setLocalConfig(CONFIG_DATE_TILL + mainwin.getAZ().title,
                tillDate != null && tillDate.length() >= 10 ? tillDate.substring(0, 10) : tillDate);

        super.close();
    }

    private double parseStartBalance() {
        try {
            return Double.parseDouble(jTStartBalance.getText().trim().replace(",", "."));
        } catch (NumberFormatException e) {
            return 0.0;
        }
    }

    private ReportIncomeExpenseRenderer createRenderer() {
        gui_to_var();
        return createRenderer(parseStartBalance());
    }

    /** Builds and fills the renderer; must not touch Swing components. */
    private ReportIncomeExpenseRenderer createRenderer(double startBalance) {
        ReportIncomeExpenseRenderer renderer = new ReportIncomeExpenseRenderer(
                getTransaction(), mainwin.getAZ(), startBalance, dateFrom, dateTill);
        renderer.collectData();
        return renderer;
    }

    private void generateReport() {
        new AutoMBox(getTitle()) {
            @Override
            public void do_stuff() throws Exception {
                setWaitCursor();
                ReportIncomeExpenseRenderer renderer = createRenderer();
                jReport.setText(renderer.render());
                jReport.setCaretPosition(0);
                setWaitCursor(false);
            }
        };
    }

