    // ------------------------------------------------------------------
    // ODS export
    // ------------------------------------------------------------------
    private void exportToODS() {
        if (jReport.getText() == null || jReport.getText().trim().isEmpty()) {
            return;
        }

        JFileChooser chooser = new JFileChooser(mainwin.getLastOpenPath());
        chooser.setDialogTitle("Export as ODS");
        chooser.setSelectedFile(new File("Einnahmen-Ausgaben.ods"));
        if (chooser.showSaveDialog(this) != JFileChooser.APPROVE_OPTION) {
            return;
        }

        final File targetFile;
        File selected = chooser.getSelectedFile();
        if (!selected.getName().toLowerCase().endsWith(".ods")) {
            targetFile = new File(selected.getAbsolutePath() + ".ods");
        } else {
            targetFile = selected;
        }
        mainwin.setLastOpenPath(targetFile.getParent());

        new AutoMBox("Export ODS") {
            @Override
            public void do_stuff() throws Exception {
                setWaitCursor();
                ReportIncomeExpenseRenderer renderer = createRenderer();
                // render() fills the HTML preview; the data is already collected
                renderer.render();
                writeOds(targetFile, renderer);
                setWaitCursor(false);
            }
        };
    }

    /**
     * Exports the ODS into a chosen directory and writes the referenced bill
     * documents into the sub directory {@value #BELEGE_DIR_NAME}.
     */
    private void exportToODSWithBills() {
        if (jReport.getText() == null || jReport.getText().trim().isEmpty()) {
            return;
        }

        JFileChooser chooser = new JFileChooser(mainwin.getLastOpenPath());
        chooser.setDialogTitle("Export ODS with Bills - choose directory");
        chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);
        chooser.setAcceptAllFileFilterUsed(false);
        if (chooser.showSaveDialog(this) != JFileChooser.APPROVE_OPTION) {
            return;
        }

        final File exportDir = chooser.getSelectedFile();
        mainwin.setLastOpenPath(exportDir.getAbsolutePath());
        final File odsFile = new File(exportDir, "Einnahmen-Ausgaben.ods");
        final File belegeDir = new File(exportDir, BELEGE_DIR_NAME);

        // read the input fields on the EDT, the worker only uses the values
        gui_to_var();
        final double startBalance = parseStartBalance();

        if (odsFile.exists() && JOptionPane.showConfirmDialog(this,
                "Overwrite existing file?\n" + odsFile.getAbsolutePath(),
                getTitle(), JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION) {
            return;
        }

        final ExportProgressDialog progress = new ExportProgressDialog(this, "Export ODS with Bills");

        new SwingWorker<Integer, Void>() {
            private Exception failure;

            @Override
            protected Integer doInBackground() {
                try {
                    ReportIncomeExpenseRenderer renderer = createRenderer(startBalance);
                    renderer.render();

                    List<BillRef> bills = renderer.getAllBills();
                    int steps = bills.size() + 2;
                    progress.initProgress(steps);
                    progress.setProgress(0, "Creating report ...");

                    if (!belegeDir.exists() && !belegeDir.mkdirs()) {
                        throw new IOException("Cannot create directory: " + belegeDir.getAbsolutePath());
                    }

                    progress.setProgress(1, "Saving spreadsheet ...");
                    writeOds(odsFile, renderer);

                    int step = 2;
                    for (BillRef bill : bills) {
                        progress.setProgress(step, "Copying bill: " + bill.getExportName());
                        writeBillFile(bill, belegeDir);
                        step++;
                    }

                    progress.setProgress(steps, "Finished");
                    return bills.size();
                } catch (Exception ex) {
                    failure = ex;
                    return -1;
                }
            }

            @Override
            protected void done() {
                progress.closeDialog();
                if (failure != null) {
                    JOptionPane.showMessageDialog(ReportIncomeExpense.this,
                            failure.getMessage(), "Export ODS with Bills", JOptionPane.ERROR_MESSAGE);
                    return;
                }
                try {
                    int count = get();
                    JOptionPane.showMessageDialog(ReportIncomeExpense.this,
                            "Export finished.\nSpreadsheet: " + odsFile.getAbsolutePath()
                            + "\nBills: " + count + " in " + belegeDir.getAbsolutePath(),
                            "Export ODS with Bills", JOptionPane.INFORMATION_MESSAGE);
                } catch (Exception ex) {
                    JOptionPane.showMessageDialog(ReportIncomeExpense.this,
                            String.valueOf(ex.getMessage()), "Export ODS with Bills",
                            JOptionPane.ERROR_MESSAGE);
                }
            }
        }.execute();

        progress.setVisible(true);
    }

    /** Writes the document of one bill into the belege directory. */
    private void writeBillFile(BillRef ref, File belegeDir) throws Exception {
        DBBill bill = new DBBill();
        bill.idx.loadFromCopy(ref.getBillIdx());
        getTransaction().fetchTableWithPrimkey(bill);

        byte[] data;
        if (ref.getExportName().toLowerCase(Locale.ROOT).endsWith(".odt")
                && bill.odt_data.value != null && bill.odt_data.value.length > 0) {
            data = bill.odt_data.value;
        } else {
            data = bill.pdf_data.value;
        }
        if (data == null || data.length == 0) {
            data = bill.odt_data.value;
        }
        if (data == null || data.length == 0) {
            return; // no document stored for this bill
        }

        File target = new File(belegeDir, ref.getExportName());
        try (FileOutputStream fos = new FileOutputStream(target)) {
            fos.write(data);
        }
    }

    private void writeOds(File targetFile, ReportIncomeExpenseRenderer renderer) throws Exception {
        OdfSpreadsheetDocument spreadsheet = OdfSpreadsheetDocument.newSpreadsheetDocument();

        OdfTable table = spreadsheet.getSpreadsheetTables().get(0);
        table.setTableName("Einnahmen-Ausgaben");
        // the default sheet of a new document is not printable
        table.getOdfElement().setTablePrintAttribute(true);

        List<String> monthLabels = renderer.getMonthLabels();
        int columnCount = monthLabels.size() + 2;

        ensureColumns(table, columnCount);

        // odfdom does not allow removing the last remaining row of a sheet,
        // so the existing empty row is reused for the first report line.
        OdfTableRow periodRow = table.getRowCount() > 0 ? table.getRowByIndex(0) : table.appendRow();
        setText(periodRow, 0, "Zeitraum: " + renderer.getStartDateLabel()
                + " - " + renderer.getEndDateLabel(), true, null);

        OdfTableRow startRow = appendCleanRow(table);
        setText(startRow, 0, "Startkontostand per " + renderer.getStartDateLabel()
                + " : Eur " + money(renderer.getStartBalance()), true, null);

        appendCleanRow(table); // spacer

        boolean firstSection = true;
        firstSection = writeSection(table, "Ausgaben " + renderer.getPeriodLabel(),
                renderer.getExpenseRows(), renderer.getExpenseMonthTotals(),
                renderer.getExpenseTotal(), monthLabels, firstSection);

        appendCleanRow(table); // spacer
        firstSection = writeSection(table, "Einnahmen " + renderer.getPeriodLabel(),
                renderer.getIncomeRows(), renderer.getIncomeMonthTotals(),
                renderer.getIncomeTotal(), monthLabels, firstSection);

        if (!renderer.getLiabilityRows().isEmpty()) {
            appendCleanRow(table); // spacer
            writeSection(table, "Verbindlichkeiten " + renderer.getPeriodLabel(),
                    renderer.getLiabilityRows(), renderer.getLiabilityMonthTotals(),
                    renderer.getLiabilityTotal(), monthLabels, firstSection);
        }

        appendCleanRow(table); // spacer
        OdfTableRow balanceRow = appendCleanRow(table);
        setText(balanceRow, 0, "Kontostand per " + renderer.getEndDateLabel()
                + " : Eur " + money(renderer.getEndBalance()), true, null);

        setColumnWidths(table, monthLabels.size());

        File belegeDir = new File(targetFile.getAbsoluteFile().getParentFile(), BELEGE_DIR_NAME);
        writeBookingLinesSheet(spreadsheet, renderer, belegeDir);

        try (FileOutputStream fos = new FileOutputStream(targetFile)) {
            spreadsheet.save(fos);
        }
    }

    /**
     * Writes one report section (header row, account class rows, total row).
     *
     * @param withMonthLabels true for the first section (month labels are only
     *                        written once, like on the printed sheet)
     * @return always false, so the next call does not repeat the month labels
     */
    private boolean writeSection(OdfTable table, String title, List<ReportIncomeExpenseRenderer.Row> rows,
            double[] monthTotals, double total, List<String> monthLabels, boolean withMonthLabels) {
        int monthCount = monthLabels.size();

        OdfTableRow header = appendCleanRow(table);
        setText(header, 0, title, true, COLOR_HEADER);
        for (int i = 0; i < monthCount; i++) {
            setText(header, 1 + i, withMonthLabels ? monthLabels.get(i) : "", true, COLOR_HEADER);
        }
        setText(header, monthCount + 1, "Summe", true, COLOR_HEADER);

        int number = 1;
        for (ReportIncomeExpenseRenderer.Row row : rows) {
            OdfTableRow dataRow = appendCleanRow(table);
            setText(dataRow, 0, number + ". " + row.getName(), false, null);
            for (int i = 0; i < monthCount; i++) {
                setMoney(dataRow, 1 + i, row.getValue(i), false, null);
            }
            setMoney(dataRow, monthCount + 1, row.getTotal(), false, null);
            number++;
        }

        OdfTableRow totalRow = appendCleanRow(table);
        setText(totalRow, 0, "Summe", true, null);
        for (int i = 0; i < monthCount; i++) {
            setMoney(totalRow, 1 + i, monthTotals[i], true, null);
        }
        setMoney(totalRow, monthCount + 1, total, true, null);

        return false;
    }

    private void writeBookingLinesSheet(OdfSpreadsheetDocument spreadsheet,
            ReportIncomeExpenseRenderer renderer, File belegeDir) {
        OdfTable table = OdfTable.newTable(spreadsheet);
        table.setTableName("Buchungszeilen");
        ensureColumns(table, 5);

        OdfTableRow header = table.getRowCount() > 0 ? table.getRowByIndex(0) : appendCleanRow(table);
        setText(header, 0, "Datum", true, null);
        setText(header, 1, "Konto", true, null);
        setText(header, 2, "Beschreibung", true, null);
        setText(header, 3, "Betrag (€)", true, null);
        setText(header, 4, "Beleg", true, null);

        for (DBBookingLine bl : renderer.getBookingLines()) {
            OdfTableRow row = appendCleanRow(table);

            String date = "";
            if (bl.date != null && bl.date.getValue() != null) {
                date = DATE_FORMAT.format(bl.date.getValue().toInstant()
                        .atZone(ZoneId.systemDefault()).toLocalDate());
            }
            setText(row, 0, date, false, null);

            String accountClass = "";
            if (bl.account_class != null && bl.account_class.getValue() != null
                    && !bl.account_class.getValue().isEmpty()) {
                accountClass = bl.account_class.getValue();
            }
            setText(row, 1, accountClass, false, null);

            String description = "";
            if (bl.comment != null && bl.comment.getValue() != null && !bl.comment.getValue().isEmpty()) {
                description = bl.comment.getValue();
            } else if (bl.line != null && bl.line.getValue() != null) {
                description = bl.line.getValue();
            }
            setText(row, 2, description, false, null);

            double amount = bl.amount != null ? bl.amount.getValue() : 0.0;
            setMoney(row, 3, amount, false, null);

            List<BillRef> bills = renderer.getBillsForBookingLine(bl.idx.getValue());
            if (!bills.isEmpty()) {
                setLinks(row, 4, bills, belegeDir);
            }
        }

        setColumnWidths(table, new String[] { "2.6cm", "4.5cm", "8cm", "2.8cm", "7cm" });
    }

    // ---- ODS helpers ----

    /**
     * odfdom's appendRow() copies the cell style names of the previous row, which
     * would spread the header background (and bold) over all following rows.
     * The cloned style names are removed so every new row starts unstyled.
     */
    private static OdfTableRow appendCleanRow(OdfTable table) {
        OdfTableRow row = table.appendRow();
        for (int i = 0; i < table.getColumnCount(); i++) {
            row.getCellByIndex(i).getOdfElement().removeAttribute("table:style-name");
        }
        return row;
    }

    private static void ensureColumns(OdfTable table, int columnCount) {
        if (table.getColumnCount() < columnCount) {
            table.appendColumns(columnCount - table.getColumnCount());
        }
    }

    private static void setText(OdfTableRow row, int column, String value, boolean bold, String background) {
        if ((value == null || value.isEmpty()) && !bold && background == null) {
            return;
        }
        OdfTableCell cell = row.getCellByIndex(column);
        cell.setStringValue(value != null ? value : "");
        if (bold) {
            cell.getOdfElement().setProperty(OdfTextProperties.FontWeight, "bold");
        }
        if (background != null) {
            cell.getOdfElement().setProperty(OdfTableCellProperties.BackgroundColor, background);
        }
    }

    private static void setMoney(OdfTableRow row, int column, double value, boolean bold, String background) {
        boolean hasValue = value != 0.0;
        if (!hasValue && !bold && background == null) {
            return;
        }
        OdfTableCell cell = row.getCellByIndex(column);
        if (hasValue) {
            cell.setDoubleValue(value);
            cell.setFormatString("€ #,##0.00");
            if (value < 0.0) {
                cell.getOdfElement().setProperty(OdfTextProperties.Color, COLOR_NEGATIVE);
            }
        }
        if (bold) {
            cell.getOdfElement().setProperty(OdfTextProperties.FontWeight, "bold");
        }
        if (background != null) {
            cell.getOdfElement().setProperty(OdfTableCellProperties.BackgroundColor, background);
        }
    }

    private static String money(double value) {
        return String.format(MONEY_LOCALE, "%,.2f", value);
    }

    /**
     * Writes one hyperlink per bill into the cell. Multiple bills result in
     * multiple lines inside the same cell, each linking to the file below the
     * {@code belege} directory.
     */
    private static void setLinks(OdfTableRow row, int column, List<BillRef> bills, File belegeDir) {
        OdfTableCell cell = row.getCellByIndex(column);
        TableTableCellElementBase cellElement = cell.getOdfElement();
        while (cellElement.getFirstChild() != null) {
            cellElement.removeChild(cellElement.getFirstChild());
        }
        for (BillRef bill : bills) {
            TextPElement paragraph = new TextPElement((OdfFileDom) cellElement.getOwnerDocument());
            cellElement.appendChild(paragraph);
            TextAElement link = paragraph.newTextAElement(
                    toFileUri(new File(belegeDir, bill.getExportName())), "simple");
            link.setTextContent(bill.getExportName());
        }
    }

    /**
     * Absolute {@code file:} URI for a bill document.
     *
     * LibreOffice resolves relative cell hyperlinks against the document path
     * including the ODS file name, which results in a broken
     * {@code .../report.ods/belege/file.pdf} location. Absolute URIs work.
     */
    private static String toFileUri(File file) {
        String uri = file.toURI().toASCIIString();
        if (uri.startsWith("file:/") && !uri.startsWith("file:///")) {
            uri = "file:///" + uri.substring("file:/".length());
        }
        return uri;
    }

    /**
     * Sets explicit column widths. setWidth() in odfdom 0.10.0 fails on locale
     * specific decimal values, so the width is written as style property.
     */
    private static void setColumnWidths(OdfTable table, int monthCount) {
        String[] widths = new String[monthCount + 2];
        widths[0] = "5.0cm";
        for (int i = 1; i <= monthCount; i++) {
            widths[i] = "2.3cm";
        }
        widths[monthCount + 1] = "2.8cm";
        setColumnWidths(table, widths);
    }

    private static void setColumnWidths(OdfTable table, String[] widths) {
        for (int i = 0; i < table.getColumnCount() && i < widths.length; i++) {
            org.odftoolkit.odfdom.doc.table.OdfTableColumn column = table.getColumnByIndex(i);
            if (column != null) {
                column.getOdfElement().setProperty(
                        org.odftoolkit.odfdom.dom.style.props.OdfTableColumnProperties.ColumnWidth, widths[i]);
            }
        }
    }

